// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DAO} from "../src/DAO.sol";

contract InvMutTest is Test {
    DAO c;
    function setUp() public { c = new DAO(); }
    function testFuzz_property(address caller, address recipient, uint256 amount) public {
        vm.assume(caller != address(0));
        vm.assume(recipient != address(0));
        uint256 beforeCount = c.proposalCount();
        vm.prank(caller);
        c.newGrantProposal(recipient, amount);
        uint256 afterCount = c.proposalCount();
        assertTrue(afterCount == beforeCount + 1);
    }
}
